export default scene({
  mode: '2d',
  orbit: false,
  background: Color.BLACK,
  end: 'hold',
  audio: 'bf168c3193adf0650860c96b0e6169203206687296940bb373eab1498c2656cb.beat-1'
}, s => {
  const D = 72.86420833333334;

  // Cue times (s) re-timed to the rewritten narration; keys kept from the first version.
  const W = {
    w13: 13.839, w20: 16.15, w24: 18.634, w25: 19.772,
    w28: 21.792, w37: 33.484, w43: 33.484, w44: 49.459,
    w49: 54.347, w54: 60.57, w57: 63.182, w58: 66.259
  };

  const sel = s.select('mass-select', {
    label: 'Mass',
    options: ['Narrated', 'None', 'Star', 'Black hole'],
    default: 'Narrated', position: [.697, .63], width: 174
  });
  const light = s.toggle('ray-toggle', {
    label: 'Light ray', default: true, position: [.697, .705], width: 174
  });
  // A boolean alone cannot distinguish untouched playback from an explicit On.
  // Entering inspection shows the whole path immediately; Show/Hide then
  // stays independent of both the Mass setting and the narration clock.
  const inspectPlanet = s.toggle('orbit-toggle', {
    label: 'Inspect planet path', default: false, position: [.697, .774], width: 174
  });
  const planetChoice = inspectPlanet ? s.select('planet-visibility', {
    label: 'Planet path', options: ['Show', 'Hide'], default: 'Show',
    position: [.697, .84], width: 174
  }) : 'Narrated';
  const planet = planetChoice !== 'Hide';

  const auto = sel === 'Narrated';
  const timedPlanet = auto && planetChoice === 'Narrated';
  const planetVisible = t => planet && (!timedPlanet || t >= W.w44);
  const manual = sel === 'None' ? 0 : sel === 'Black hole' ? 2 : 1;
  const preset = t => auto ? (t >= W.w13 && t < W.w25 ? 0 : 1) : manual;
  const clamp = x => Math.max(0, Math.min(1, x));
  const lerp = (a, b, t) => a + (b - a) * t;
  const sample = (n, f) => Array.from({length: n + 1}, (_, i) => f(i / n));

  const ink = (id, text, y, fontSize, fill) => s.text(id, {
    text, fontSize, fill, position: [0, y], viewportOffset: [.305, 0]
  });
  const show = (h, fn) => s.bind(h, [s.time], t => ({opacity: fn(t) ? 1 : 0}));

  ink('folio', 'GENERAL RELATIVITY', 2.63, .25, Color.BLUE_B);
  show(ink('light-title', 'Follow the light', 2.03, .45, Color.WHITE), t => t < W.w44);
  show(ink('orbit-title', 'Follow the planet', 2.03, .44, Color.WHITE),
    t => t >= W.w44 && t < W.w58);
  show(ink('both-title', 'Free motion', 2.03, .45, Color.WHITE), t => t >= W.w58);

  s.line('rule', {
    points: [[-1.42, 1.58], [1.42, 1.58]],
    viewportOffset: [.305, 0], stroke: Color.BLUE_E, strokeWidth: .018
  });

  const info = (id, msg, y, col, fn) => show(ink(id, msg, y, .265, col), fn);
  for (let k = 0; k < 3; k++) {
    info('preset-' + k,
      ['No mass  /  flat grid', 'Star  /  curved grid', 'Black hole  /  larger mass'][k],
      1.15, Color.BLUE_B, t => preset(t) === k);
  }
  info('entry', 'Incoming light', .62, Color.YELLOW, t => light && t < W.w13 && auto);
  info('guide-key', 'Dashed: straight guide', .62, Color.GREY_A,
    t => light && (!auto || t >= W.w13) && t < W.w44);
  info('angle-key', 'Deflected light', .12, Color.YELLOW,
    t => light && preset(t) !== 0 && t >= W.w37 && t < W.w44);
  info('orbit-key', 'Closest approaches', .62, Color.TEAL_A,
    t => planet && preset(t) !== 0 && t >= W.w49);
  info('free-key', 'Planet: unbound', .12, Color.TEAL_A,
    t => planetVisible(t) && preset(t) === 0);

  ink('note', 'schematic · time not shown', -.50, .26, Color.GREY_B);
  s.text('rotate-note', {
    text: 'Drag the sphere to rotate', position: [0, -2.96],
    viewportOffset: [-.168, 0], fontSize: .24, fill: Color.GREY_B
  });

  s.view('encounter', {
    rect: [0, .045, .664, .815],
    orbit: true, orbitHitTest: 'geometry',
    camera: {yaw: .33, pitch: -.21, height: 7, distance: 27, perspective: .6}
  }, v => {
    const ball = (id, p, r, fill) => v.sphere(id, {
      position: p, radius: r, fill, stroke: Color.NONE
    });
    const stroke = (id, points, col, width, opacity = 1) => v.path(id, {
      points, fill: Color.NONE, stroke: col, strokeWidth: width, opacity
    });

    // The spherical fill supplies the full-disk geometry hit for native orbit.
    // Keep the contour centered; a translating surface grab would consume orbit.
    v.sphere('shell-surface', {
      radius: 3.32, fill: Color.WHITE, opacity: .021, stroke: Color.NONE
    });
    const rim = v.path('rotation-shell', {
      points: sample(96, u => [
        3.32 * Math.cos(2 * Math.PI * u), 3.32 * Math.sin(2 * Math.PI * u), 0
      ]),
      billboard: true, stroke: Color.GREY_C, strokeWidth: .012,
      fill: Color.NONE, opacity: .33
    });
    v.behavior(rim, {
      type: 'drag', plane: 'xy', bounds: {min: [0, 0, 0], max: [0, 0, 0]}
    });

    for (const k of (auto ? [0, 1] : [manual])) {
      const grid = [], key = 'm' + k + '-', mass = k !== 0;
      const strength = [0, .85, 1.04][k], levels = [-1.92, -.64, .64, 1.92];

      for (let axis = 0; axis < 3; axis++) {
        for (let j = 0; j < 4; j++) {
          for (let h = 0; h < 4; h++) {
            const a = levels[j], b = levels[h];
            const L = Math.min(2.75, Math.sqrt(3.21 * 3.21 - a * a - b * b));
            const pts = sample(mass ? 24 : 1, u => {
              const x = (u * 2 - 1) * L;
              const f = 1 - strength * Math.exp(-(x * x + a * a + b * b) / 2.8);
              return (axis === 0 ? [x, a, b] : axis === 1 ? [b, x, a] : [a, b, x])
                .map(c => c * f);
            });
            const central = Math.abs(a) < 1 && Math.abs(b) < 1;
            grid.push(stroke(key + 'grid-' + axis + '-' + j + h, pts,
              central ? Color.BLUE_B : Color.BLUE,
              central ? .023 : .016, central ? .82 : .46));
          }
        }
      }

      const lattice = v.group(key + 'space-grid', grid);
      s.bind(lattice, [s.time], t => ({opacity: t >= W.w44 && planet ? .49 : 1}));
      const pieces = [lattice];

      if (mass) {
        pieces.push(v.sphere(key + 'mass', {
          radius: k === 1 ? .44 : .53,
          fill: k === 1 ? Color.GREY_A : Color.GREY_E, stroke: Color.NONE,
          material: {roughness: .57, specular: .35},
          outline: {color: k === 1 ? Color.GREY_B : Color.GREY, width: .014, creaseAngle: Math.PI}
        }));
      }

      // Join the two ray asymptotes smoothly, independently of the lattice map.
      const bit = x => x <= -.95 ? 0 : x >= .95 ? x : (x + .95) * (x + .95) / 3.8;
      const ray = u => {
        const x = lerp(-2.96, 2.84, u);
        return [x, 1.13 - [0, .49, .74][k] * bit(x), 0];
      };

      const prefix = (pts, u) => {
        const q = clamp(u) * (pts.length - 1), i = Math.floor(q);
        const p = pts[i], n = pts[Math.min(i + 1, pts.length - 1)];
        const tip = p.map((x, d) => lerp(x, n[d], q - i));
        return pts.map((x, j) => j <= i ? x : tip);
      };

      if (light) {
        const dash = [];
        for (let i = 0; i < 28; i++) {
          const x = -2.99 + .22 * i;
          dash.push(stroke(key + 'dash-' + i,
            [[x, 1.13, -.014], [x + .13, 1.13, -.014]],
            Color.GREY_A, .029, .85));
        }
        const guide = v.group(key + 'guide', dash);
        show(guide, t => !auto || t >= W.w13);
        pieces.push(guide);

        const pts = sample(72, ray);
        const advance = t => !auto ? 1 : t < W.w13 ? .265
          : k === 0 ? clamp((t - W.w20) / (W.w24 - W.w20))
          : clamp((t - W.w28) / (W.w37 - W.w28));

        const beam = stroke(key + 'light-ray', pts, Color.YELLOW, .043);
        s.bind(beam, [s.time], t => ({
          points: prefix(pts, advance(t)),
          opacity: planet && t >= W.w44 ? .66 : 1
        }));
        const dot = ball(key + 'ray-dot', ray(0), .076, Color.YELLOW);
        s.bind(dot, [s.time], t => ({position: ray(advance(t))}));
        pieces.push(beam, dot);
      }

      if (planet) {
        const advance = k === 2 ? 1.13 : .82, period = 2 * Math.PI + advance;
        const inPlane = (r, theta) => [
          r * Math.cos(theta),
          .95 * r * Math.sin(theta),
          Math.sqrt(1 - .95 * .95) * r * Math.sin(theta)
        ];
        const orbit = u => {
          if (!mass) return [lerp(-2.8, 2.8, u), -.82, .2];
          const phi = u * 3 * period;
          const r = 1.35 / (1 + .51 * Math.cos(phi * 2 * Math.PI / period));
          return inPlane(r, phi - 1.47);
        };
        const prog = t => !timedPlanet ? 1
          : t <= W.w49 ? clamp((t - W.w44) / (W.w49 - W.w44)) / 3
          : t <= W.w54 ? (1 + clamp((t - W.w49) / (W.w54 - W.w49))) / 3
          : (2 + clamp((t - W.w54) / (W.w57 - W.w54))) / 3;

        const pts = sample(mass ? 288 : 2, orbit);
        const track = stroke(key + 'orbit', pts, Color.TEAL, .032);
        s.bind(track, [s.time], t => ({points: prefix(pts, prog(t))}));
        const dot = ball(key + 'planet', orbit(0), .10, Color.TEAL_A);
        s.bind(dot, [s.time], t => ({position: orbit(prog(t))}));

        const members = [track, dot];
        if (mass) {
          for (let j = 1; j <= 2; j++) {
            const p = orbit(j / 3);
            const marker = v.group(key + 'peri-' + j, [
              stroke(key + 'tick-' + j, [p.map(x => x * .60), p.map(x => x * 1.18)],
                Color.TEAL_A, .044),
              ball(key + 'pin-' + j, p, .066, Color.TEAL_A)
            ]);
            show(marker, t => !timedPlanet || t >= (j === 1 ? W.w49 : W.w54));
            members.push(marker);
          }
          const angle = stroke(key + 'apsidal-advance',
            sample(16, u => inPlane(.62, advance * (1 + u) - 1.47)),
            Color.TEAL_A, .026);
          show(angle, t => !timedPlanet || t >= W.w54);
          members.push(angle);
        }
        const pg = v.group(key + 'planet-orbit', members);
        show(pg, planetVisible);
        pieces.push(pg);
      }

      const g = v.group(key + 'preset', pieces);
      show(g, t => preset(t) === k);
    }
  });
  s.wait(D);
});
